  1 import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
  2 import type { ChatItem } from "../src/lib/streamReducer.js";
  3 
  4 function visibleOutput(item: ChatItem): boolean {
  5   return (
  6     item.kind !== "user" &&
  7     !(item.kind === "assistant" && item.done && !item.text && !item.reasoning)
  8   );
  9 }
 10 
 11 /** Transport snapshots can recreate objects without adding visible output. */
 12 export function outputChanged(previous: ChatItem | undefined, item: ChatItem): boolean {
 13   if (!visibleOutput(item) || previous === item) return false;
 14   if (!previous || previous.kind !== item.kind) return true;
 15   switch (item.kind) {
 16     case "user":
 17       return false;
 18     case "assistant":
 19       return (
 20         previous.kind === "assistant" &&
 21         (previous.text !== item.text ||
 22           previous.reasoning !== item.reasoning ||
 23           previous.done !== item.done)
 24       );
 25     case "tool":
 26       return (
 27         previous.kind === "tool" &&
 28         (previous.result !== item.result ||
 29           previous.summary !== item.summary ||
 30           previous.done !== item.done ||
 31           previous.error !== item.error ||
 32           JSON.stringify(previous.args) !== JSON.stringify(item.args))
 33       );
 34     case "subagent":
 35       return (
 36         previous.kind === "subagent" &&
 37         (previous.label !== item.label || previous.status !== item.status)
 38       );
 39     case "system":
 40     case "system_error":
 41       return (
 42         (previous.kind === "system" || previous.kind === "system_error") &&
 43         previous.text !== item.text
 44       );
 45   }
 46 }
