 48 /** Follow the live tail until the reader scrolls up. Session changes and explicit
 49  * jumps resume following; reconnect/history hydration clear notices without
 50  * disturbing an older paragraph the reader has chosen to keep on screen. */
 51 export function useLatestMessages({
 52   items,
 53   scope,
 54   connection,
 55   loading,
 56   active,
 57   approvalCount,
 58 }: {
 59   items: ChatItem[];
 60   scope: string;
 61   connection: string;
 62   loading: boolean;
 63   active: boolean;
 64   approvalCount: number;
 65 }) {
 66   const listRef = useRef<HTMLDivElement>(null);
 67   const contentRef = useRef<HTMLDivElement>(null);
 68   const following = useRef(true);
 69   const programmaticTop = useRef<number | null>(null);
 70   const snappedSize = useRef<{ width: number; height: number } | null>(null);
 71   const previous = useRef(new Map<string, ChatItem>());
 72   const unread = useRef(new Set<string>());
 73   const identity = useRef({ scope, connection, loading, active });
 74   const [showJump, setShowJump] = useState(false);
 75   const [newOutputCount, setNewOutputCount] = useState(0);
 76   const clearNotices = useCallback(() => {
 77     unread.current.clear();
 78     setNewOutputCount(0);
 79   }, []);
 80   const snap = useCallback(() => {
 81     const list = listRef.current;
 82     if (!list) return;
 83     list.scrollTop = list.scrollHeight;
 84     programmaticTop.current = list.scrollTop;
 85     snappedSize.current = { width: list.clientWidth, height: list.clientHeight };
 86   }, []);
 87   const resume = useCallback(() => {
 88     following.current = true;
 89     clearNotices();
 90     setShowJump(false);
 91     snap();
 92   }, [clearNotices, snap]);
 93 
 94   const onScroll = useCallback(() => {
 95     const list = listRef.current;
 96     if (!list || !active) return;
 97     const size = snappedSize.current;
 98     // Viewport/composer reflow can dispatch scroll before ResizeObserver. Keep
 99     // an existing follow decision through that layout event, then measure anew.
100     if (
101       following.current &&
102       size &&
103       (size.width !== list.clientWidth || size.height !== list.clientHeight)
104     ) {
105       snap();
106       setShowJump(false);
107       return;
108     }
109     const near = list.scrollHeight - list.scrollTop - list.clientHeight <= 100;
110     // A bottom snap dispatches its scroll event after more content may arrive.
111     // Do not mistake that delayed event for the reader leaving the live tail.
112     if (
113       programmaticTop.current !== null &&
114       Math.abs(list.scrollTop - programmaticTop.current) <= 2
115     ) {
116       programmaticTop.current = null;
117       setShowJump(!near && !following.current);
118       return;
119     }
120     programmaticTop.current = null;
121     following.current = near;
122     setShowJump(!near);
123     if (near) clearNotices();
124   }, [active, clearNotices, snap]);
125 
126   useLayoutEffect(() => {
127     const before = identity.current;
128     const changedScope = before.scope !== scope;
129     const reset =
130       changedScope ||
131       before.connection !== connection ||
132       before.loading !== loading ||
133       before.active !== active;
134     identity.current = { scope, connection, loading, active };
135     const next = new Map(items.filter(visibleOutput).map((item) => [item.id, item]));
136     if (reset) {
137       clearNotices();
138       if (changedScope) {
139         following.current = true;
140         programmaticTop.current = null;
141         setShowJump(false);
142       }
143     } else if (active && connection === "open" && !loading && !following.current) {
144       for (const item of items) {
145         if (outputChanged(previous.current.get(item.id), item)) unread.current.add(item.id);
146       }
147       for (const id of unread.current) if (!next.has(id)) unread.current.delete(id);
148       setNewOutputCount(unread.current.size);
149     }
150     previous.current = next;
151     if (active && following.current) snap();
152   }, [items, scope, connection, loading, active, approvalCount, clearNotices, snap]);
153 
154   useEffect(() => {
155     const list = listRef.current;
156     const content = contentRef.current;
157     if (!active || !list || !content || typeof ResizeObserver === "undefined") return;
158     const observer = new ResizeObserver(() => {
159       if (following.current) snap();
160       else if (list.scrollHeight - list.scrollTop - list.clientHeight <= 100) resume();
161       else setShowJump(true);
162     });
163     observer.observe(list);
164     observer.observe(content);
165     return () => observer.disconnect();
166   }, [active, resume, snap]);
167 
168   const jumpToLatest = useCallback(() => {
169     resume();
170     listRef.current?.focus({ preventScroll: true });
171   }, [resume]);
172   return { listRef, contentRef, onScroll, showJump, newOutputCount, jumpToLatest, resume };
173 }
